function validate([power, damage, health]) {
  if (power < 1 || power > 10000) return 'power is between 1 and 10^4.';
  if (damage.length < 1 || damage.length > 100000) return 'damage needs 1 to 10^5 values.';
  if (health.length !== damage.length) return 'damage and health must have the same length.';
  if (damage.some(v => v < 1 || v > 10000)) return 'Each damage is between 1 and 10^4.';
  if (health.some(v => v < 1 || v > 10000)) return 'Each health is between 1 and 10^4.';
  return null;
}

