function minDamage(power, damage, health) {
  const time = health.map(h => Math.ceil(h / power));
  const order = damage.map((_, i) => i);
  order.sort((a, b) => time[a] * damage[b] - time[b] * damage[a]);
  let elapsed = 0;
  let total = 0;
  for (const i of order) {
    elapsed += time[i];
    total += damage[i] * elapsed;
  }
  return total;
}

