function minDamage(power, damage, health) {
  // Try every possible attack, second by second, remembering the best result for each vector of remaining health.
  const memo = new Map();
  const fight = left => {
    const key = left.join(',');
    if (memo.has(key)) return memo.get(key);
    let incoming = 0;
    for (let i = 0; i < left.length; i++) if (left[i] > 0) incoming += damage[i];
    let best = incoming === 0 ? 0 : Infinity;
    for (let i = 0; i < left.length; i++) {
      if (left[i] <= 0) continue;
      const next = left.slice();
      next[i] -= power;
      best = Math.min(best, incoming + fight(next));
    }
    memo.set(key, best);
    return best;
  };
  return fight(health.slice());
}

