function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1900, 2000);
    const power = [pick(1, 10), pick(1, 300), pick(1, 10000)][pick(0, 2)];
    return [power, Array.from({ length: n }, () => pick(1, 10000)), Array.from({ length: n }, () => pick(1, 10000))];
  }
  // Keep the brute force's search small: the product of (hits needed + 1) stays at most 3000.
  for (;;) {
    const n = pick(1, 5);
    const power = pick(1, 5);
    const top = [5, 20, 10000][pick(0, 2)];
    const damage = Array.from({ length: n }, () => pick(1, top));
    const health = Array.from({ length: n }, () => pick(1, 15));
    const states = health.reduce((product, h) => product * (Math.ceil(h / power) + 1), 1);
    if (states <= 3000) return [power, damage, health];
  }
}
